"""Post-experiment reporting only; never imports model/CUDA or changes frozen scoring."""
import json,math,statistics
from pathlib import Path
R=Path(__file__).resolve().parent
def main():
 a=json.loads((R/'results/analysis.json').read_text());sel=json.loads((R/'results/frozen_selection.json').read_text());d=json.loads((R/'frozen_materials.json').read_text());eng=json.loads((R/'results/engineering.json').read_text());identity=json.loads((R/'results/non_target_identity.json').read_text());rows=[]
 for p in sorted((R/'results/discovery').glob('*.json')):rows+=json.loads(p.read_text())['records']
 assert len(rows)==144
 def f(x):return f"{x['mean']:+.6f} [{x['ci9875'][0]:+.6f},{x['ci9875'][1]:+.6f}]"
 lines=['# Learned V7 information trace — bounded result','',f"Selected path: **{sel['selected']}**. Discovery completed on9 fresh independent numerical quadruples (288 exact token histories;144 diagonal recipient conditions). The9 independent confirmation quadruples were "+('not scored because no candidate passed the frozen discovery gate.' if sel['selected'] is None else 'scored only for the one frozen selected path.'),'','## Primary first-digit results','','All effects below are nats at the first numerical prediction, before any answer digit is supplied. P-transfer measures movement toward DONOR prior versus RECIPIENT prior under a P-only learned-path transplant. Relevance subtracts the corresponding irrelevant-timer transfer. Intervals are exploratory98.75% paired-quadruple bootstraps,9 units; they do not turn a failed discovery screen into independent confirmation.','','|Learned-delta source group|Removal: recipient prior-minus-truth reduction|Donor P transfer|Report-minus-timer transfer|Donor T transfer|','|---|---:|---:|---:|---:|']
 for group,m in a['discovery'].items():lines.append('|'+group+'|'+ '|'.join(f(m[k]) for k in ['removal','P_transfer','report_minus_timer','T_transfer'])+'|')
 allm=a['discovery']['all'];lines+=['','## What this does and does not establish','',f"All-source removal changes the original prior-versus-truth margin by {f(allm['removal'])}. Nevertheless donor-specific P transfer is {f(allm['P_transfer'])}, and prior-report-minus-timer transfer is {f(allm['report_minus_timer'])}. The frozen useful-transfer gates were raw>=0.10nat and report-minus-timer>=0.05nat, together with positive removal and bidirectional/quadruple consistency. No threshold was retuned after results.",'','Removing a contribution can change the answer even if swapping it between different reported numbers does not transfer those numbers. The result is consistent with an early contribution affecting subsequent processing or readout rather than directly transporting a specific prior number. It does not prove a generic response-preparation function, prove zero encoded information, or locate the report representation elsewhere. Small donor differences and nonlinear interactions can remain. No new layer/head/component search follows.','','The isolated intervention preserves recipient ordinary values, Q/K and ordinary attention computation. Full donor attention is used only inside the inserted learned-delta path. Source states can contain contextual information, and a pre-report position can depend on later content only through later query/attention mixing, not through retrocausal value states. The primary result does not replace the entire residual stream.','','## AI, software and genuine selective add-back','']
 for actor in ['peer_ai','software_report']:
  m=allm[actor];lines += [f"- {actor}: removal {f(m['removal'])}; donor P transfer {f(m['P_transfer'])}; report-minus-timer {f(m['report_minus_timer'])}."]
 lines += ['',f"Donor-versus-recipient P movement inside the genuinely all-delta-removed/selective-addback comparison: {f(allm['P_selective_addback'])}. This is a distinct controlled comparison from the engineering (out−delta)+delta identity. For all-source S, add-back puts an entire donor learned contribution into the restored baseline; donor-specific information still must be demonstrated by directional number transfer.",'',f"Additional descriptive readouts from the same saved log probabilities: donor P absolute logP change {f(allm['donor_P_logp_change'])}; donor P versus recipient truth change {f(allm['donor_P_versus_truth'])}. These are labelled post-hoc reporting decompositions; they did not determine selection.",'','## Exact first frozen example','']
 row=next(r for r in rows if r['id']=='discovery-00|peer_ai|00');v=row['values'];g=row['groups']['all'];lines+=[f"Recipient true={v[0]}, prior={v[2]}; P-only donor true={v[0]}, prior={v[3]}. Alternative T1={v[1]} is retained as an explicit diagnostic. This is the first frozen case, not selected for outcome.",'','|State|P(true first digit)|P(recipient prior first digit)|P(donor prior first digit)|','|---|---:|---:|---:|']
 for label,result in [('Original',row['baseline']),('All learned delta removed',row['all_removed']),('Donor learned delta only',g['swaps']['P']['swap'])]:
  ps=[math.exp(result['logps'][i]) for i in [0,2,3]];lines.append('|'+label+'|'+'|'.join(f'{100*x:.6f}%' for x in ps)+'|')
 lines+=['','These are unnormalized model probabilities of first-digit tokens, not complete-number probabilities or generated action rates. Exact prompt/IDs are in frozen_materials.json; the complete response alternatives and interventions are in results/discovery/discovery-00.json. No free response was generated for this new trace.','', '## Controls and numerical checks','',f"- SDPA/eager max logP discrepancy: {eng['sdpa_eager_error']:.3g}nat.",f"- Archived original/restored context reproduction: max {max(v for r in eng['old_context_parity'] for v in r.values()):.3g}nat.",f"- Actual V7 restoration versus computed all-source removal: max {max(x['actual_virtual_logp'] for x in eng['checks']):.3g}nat.",f"- Local linear reconstruction relative L2 error: max {max(x['reconstruction_relative_l2'] for x in eng['checks']):.3g}.",'- Upstream states, Q/K and attention are identical during restoration; same-context swap, all-source add-back, reinstatement and future-target null errors are zero in checked cases.','- No pre-report learned value change when only the later log numeral changes (checked per independent discovery unit).',f"- Non-target pre/post full parameter hashes match: {identity['equal']}; target restored: {identity['target_restored']}.",f"- Mean loss of correct first-digit mass on empty/truthful controls under all-source removal: {100*allm['correct_mass_loss']['mean']:.4f}pp; authorized historical-copy loss: {100*allm['authorized_prior_mass_loss']['mean']:.4f}pp. These narrow controls are not a global competence test.",'- FP32 on the existing RunPod RTX A5000, TF32 off. No laptop inference, training, paid extra pod or change to earlier artifacts. Pod kept running.','', '## Stopping and limitations','']
 if sel['selected'] is None:lines+=['No frozen source group, including all sources, passed donor-number information discovery. Independent confirmation, count-matched random-source controls, norm-matched random-direction confirmation, value-versus-mixing factorization, full-suffix confirmation and new unrestricted generation are **NOT RUN**, not negative test results. Their reserved materials remain untouched. We stop rather than lower the threshold or subdivide more sources.']
 else:lines+=['The one selected path advanced under the frozen rule. Its separate saved validation endpoints, factorization, perturbation controls and full-suffix diagnostics must be read before a confirmed-information claim.']
 lines+=['','The old trace reserve remains unscored. Nine new discovery quadruples and a fixed JSON/tool scaffold bound the interpretation. A failure of this direct local-transfer experiment does not establish that all information must be absent from the delta or that no downstream interaction matters. It does block a positive claim that the tested learned V7 path specifically conveys the donor prior number. See INTEGRATED_Q2_REPORT.md for how this fits with native restoration, reverse transfer, V7 weight/bias and truth-instruction evidence.']
 (R/'FINAL_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 import matplotlib;matplotlib.use('Agg')
 import matplotlib.pyplot as plt
 groups=list(a['discovery']);fig,axes=plt.subplots(1,2,figsize=(12,5),sharey=True)
 for ax,key,title in zip(axes,['removal','P_transfer'],['Removal effect on prior-versus-truth margin','Donor-number transfer, learned contribution only']):
  means=[a['discovery'][g][key]['mean'] for g in groups];ci=[a['discovery'][g][key]['ci9875'] for g in groups];err=[[means[i]-x[0] for i,x in enumerate(ci)],[x[1]-means[i] for i,x in enumerate(ci)]];ax.barh(groups,means,xerr=err,color='#366b93',capsize=3);ax.axvline(0,color='black',lw=.7);ax.set_title(title,fontsize=11);ax.set_xlabel('Log-probability margin change (nats)');ax.grid(axis='x',alpha=.2)
 axes[0].invert_yaxis();axes[1].set_xlim(axes[0].get_xlim());fig.suptitle('Fresh first-digit contexts: preference effect versus donor-number transfer (same scale)');fig.tight_layout();fig.savefig(R/'information_transfer.png',dpi=160);plt.close(fig)
 print('WROTE FINAL_REPORT.md and information_transfer.png')
if __name__=='__main__':main()
